# capture-screenshots.ps1
# Drives the deployed Unite apps via Playwright and captures hero screenshots
# for the executive / sales / functional / technical learning packs.
#
# Output: docs/learning-packs/screens/{app}-{page}.png
#
# Prereqs:
#   - Node.js installed (Playwright runs on Node)
#   - Internet-routable access to the deployed app URLs
#   - A valid Entra account that can sign into the apps
#
# Usage:
#   .\capture-screenshots.ps1                     # hsouscloud (default), interactive sign-in
#   .\capture-screenshots.ps1 -Env OneDigital
#   .\capture-screenshots.ps1 -SignInUser foo@hso.com -StorageState .\state.json
#
# Notes:
#   - First run will pause on the login page and let YOU sign in by hand.
#     After successful sign-in, the script saves the auth state to state.json
#     so subsequent runs are unattended.
#   - Screenshots are deterministic (1920x1080, full-page).
#requires -Version 5.1

param(
    [ValidateSet('hsouscloud', 'OneDigital', 'Local')]
    [string]$Env = 'hsouscloud',

    [string]$StorageState = "$PSScriptRoot\state.json",

    [string]$OutDir = "$PSScriptRoot\..\screens"
)

$ErrorActionPreference = 'Stop'

# Resolve absolute paths
# ADR 0017: no null-coalescing (??) -- PS7-only, breaks under Windows PowerShell 5.1.
$resolvedOutDir = Resolve-Path -LiteralPath $OutDir -ErrorAction SilentlyContinue
if ($null -ne $resolvedOutDir) {
    $OutDir = $resolvedOutDir
} else {
    $OutDir = (New-Item -ItemType Directory -Force -Path $OutDir).FullName
}

# Drop a tiny Playwright script next to this PS file
$jsPath = Join-Path $PSScriptRoot 'capture.js'
$envBlock = ConvertTo-Json @{
    Env          = $Env
    StorageState = $StorageState
    OutDir       = $OutDir
} -Compress

@"
// capture.js -- generated by capture-screenshots.ps1
// Drives CashHub + CompHub + Portal pages and screenshots each.
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const config = $envBlock;

const envs = {
  hsouscloud: {
    CashHub: 'https://app-onedigital-cashhub-dev.azurewebsites.net',
    CompHub: 'https://app-onedigital-comphub-dev.azurewebsites.net',
    Portal:  null,
  },
  OneDigital: {
    CashHub: 'https://app-dev-cash-hub-01.azurewebsites.net',
    CompHub: 'https://app-dev-comp-hub-01.azurewebsites.net',
    Portal:  'https://app-dev-producer-portal-01.azurewebsites.net',
  },
  Local: {
    CashHub: 'https://localhost:7100',
    CompHub: 'https://localhost:7200',
    Portal:  'https://localhost:7300',
  },
};

// Pages to capture per app. Add or comment out as needed.
const pageMap = {
  CashHub: [
    { name: 'home',                 path: '/' },
    { name: 'statements-list',      path: '/Statements' },
    { name: 'statement-templates',  path: '/StatementTemplateList/Active' },
    { name: 'mapping-studio',       path: '/MappingStudio' },
    { name: 'cash-applications',    path: '/CashApplications' },
    { name: 'products',             path: '/Products' },
    { name: 'journals',             path: '/Journals' },
    { name: 'accruals-batches',     path: '/Accruals/Batches' },
    { name: 'accruals-preview',     path: '/Accruals/Preview' },
    { name: 'collections-cases',    path: '/Collections/Cases' },
    { name: 'research-cases',       path: '/ResearchCases' },
    { name: 'cash-deposits',        path: '/CashDeposits' },
  ],
  CompHub: [
    { name: 'home',                 path: '/' },
    { name: 'dashboard',            path: '/dashboard' },
    { name: 'comp-actuals',         path: '/compensation-actuals' },
    { name: 'comp-adjustments',     path: '/compensation-adjustments' },
    { name: 'split-intake-list',    path: '/SplitIntakeList/All' },
    { name: 'split-intake-rates',   path: '/SplitIntakeRates' },
    { name: 'split-intake-audit',   path: '/SplitIntakeAuditLog' },
    { name: 'producer-comp-rules',  path: '/ProducerCompRules' },
    { name: 'parties-all',          path: '/parties/AllParties' },
    { name: 'producers-all',        path: '/parties/AllProducers' },
    { name: 'products-admin',       path: '/Administration/Products' },
    { name: 'user-security',        path: '/UserSecurity/Setup' },
    { name: 'user-roles',           path: '/UserSecurity/UserRoles' },
    { name: 'external-users',       path: '/external-users' },
  ],
  Portal: [
    { name: 'home',                 path: '/' },
    { name: 'split-intake-list',    path: '/SplitIntakeList/Approved' },
    { name: 'reports',              path: '/reports/testreport' },
  ],
};

(async () => {
  const base = envs[config.Env];
  if (!base) {
    console.error('Unknown env: ' + config.Env);
    process.exit(1);
  }

  const useStorage = fs.existsSync(config.StorageState);
  const browser = await chromium.launch({ headless: false });
  const context = await browser.newContext({
    viewport: { width: 1920, height: 1080 },
    deviceScaleFactor: 1.5,
    storageState: useStorage ? config.StorageState : undefined,
    ignoreHTTPSErrors: true,
  });

  // First-time interactive sign-in: open the first app and wait for the user
  // to complete sign-in. Detection is automatic (URL leaves login provider),
  // with a stdin fallback if the auto-detect misses.
  if (!useStorage) {
    const apps = Object.keys(base).filter(k => base[k]);
    const firstApp = apps[0];
    const firstUrl = base[firstApp];
    const firstUrlHost = new URL(firstUrl).hostname;

    console.log('\\n' + '='.repeat(60));
    console.log(' FIRST-TIME SIGN-IN');
    console.log('='.repeat(60));
    console.log(' 1. A browser window will open at: ' + firstUrl);
    console.log(' 2. Sign in normally (Entra / Microsoft / your provider).');
    console.log(' 3. The script auto-detects when you land back at the app.');
    console.log('    If it stalls after you land, press ENTER in THIS TERMINAL.');
    console.log('='.repeat(60) + '\\n');

    const p = await context.newPage();
    await p.goto(firstUrl, { waitUntil: 'domcontentloaded' }).catch(e => {
      console.log('initial nav warning (continuing): ' + e.message);
    });

    // Strategy: wait for the URL to return to the app host AND the page to
    // settle (networkidle). Generous 10-minute timeout for the user. Fall
    // back to stdin if needed.
    const loginTimeoutMs = 10 * 60 * 1000;

    const urlWatcher = (async () => {
      try {
        await p.waitForURL(
          (u) => {
            const url = u.toString();
            const host = (() => { try { return new URL(url).hostname; } catch { return ''; } })();
            const onLoginProvider =
              host.includes('login.microsoftonline.com') ||
              host.includes('login.live.com') ||
              host.includes('accounts.google.com') ||
              host.includes('okta.com') ||
              host.includes('auth0.com') ||
              url.includes('/login') ||
              url.includes('/signin');
            return host === firstUrlHost && !onLoginProvider;
          },
          { timeout: loginTimeoutMs }
        );
        // We're back at the app host. Let it settle.
        await p.waitForLoadState('networkidle', { timeout: 30000 }).catch(() => {});
        return 'auto';
      } catch {
        return null;
      }
    })();

    const stdinWatcher = new Promise((resolve) => {
      // Resume stdin only when actually used; raw mode for single ENTER detection.
      try { process.stdin.resume(); } catch {}
      process.stdin.once('data', () => resolve('stdin'));
    });

    const winner = await Promise.race([urlWatcher, stdinWatcher]);
    try { process.stdin.pause(); } catch {}

    if (winner === 'auto') {
      console.log('\\nok Sign-in detected automatically (page returned to app host).');
    } else if (winner === 'stdin') {
      console.log('\\nok Sign-in confirmed by user (ENTER pressed).');
    } else {
      console.log('\\n! Sign-in did not complete within timeout -- saving whatever state exists.');
    }

    // Give post-login redirects/cookies a beat to fully land before saving state.
    await p.waitForTimeout(3000);

    await context.storageState({ path: config.StorageState });

    // Sanity check: did we actually get cookies?
    const saved = JSON.parse(fs.readFileSync(config.StorageState, 'utf8'));
    const cookieCount = (saved.cookies || []).length;
    const originCount = (saved.origins || []).length;
    console.log('ok Auth state saved -> ' + config.StorageState);
    console.log('  cookies: ' + cookieCount + ' - origins: ' + originCount);
    if (cookieCount === 0) {
      console.error('\\n!!! WARNING: zero cookies in saved state. Login likely did NOT complete.');
      console.error('    Delete ' + config.StorageState + ' and try again.');
    }
    await p.close();
  }

  fs.mkdirSync(config.OutDir, { recursive: true });

  let total = 0, captured = 0, failed = 0;
  for (const [appName, pages] of Object.entries(pageMap)) {
    const baseUrl = base[appName];
    if (!baseUrl) {
      console.log('[skip] ' + appName + ' not configured for ' + config.Env);
      continue;
    }
    for (const p of pages) {
      total++;
      const target = baseUrl + p.path;
      const out = path.join(config.OutDir, appName.toLowerCase() + '-' + p.name + '.png');
      try {
        const page = await context.newPage();
        await page.goto(target, { waitUntil: 'networkidle', timeout: 30000 });
        // Give Blazor a beat to render
        await page.waitForTimeout(1500);
        await page.screenshot({ path: out, fullPage: true });
        await page.close();
        captured++;
        console.log('[ok]   ' + appName + ' ' + p.name + ' -> ' + path.basename(out));
      } catch (err) {
        failed++;
        console.log('[fail] ' + appName + ' ' + p.name + ' -- ' + err.message);
      }
    }
  }

  await browser.close();
  console.log('\\nCaptured ' + captured + ' / ' + total + ' screens (' + failed + ' failed). Output: ' + config.OutDir);
})();
"@ | Set-Content -Path $jsPath -Encoding UTF8

Write-Host ""
Write-Host "ERP Unite -- capturing screenshots from $Env" -ForegroundColor Green
Write-Host ("=" * 60) -ForegroundColor DarkGray
Write-Host "Output dir : $OutDir" -ForegroundColor Gray
Write-Host "State file : $StorageState" -ForegroundColor Gray
Write-Host ""

# Ensure Playwright is installed locally
$nodeModules = Join-Path $PSScriptRoot 'node_modules'
if (-not (Test-Path (Join-Path $nodeModules 'playwright'))) {
    Write-Host "Installing Playwright (first run only) ..." -ForegroundColor Yellow
    Push-Location $PSScriptRoot
    try {
        if (-not (Test-Path (Join-Path $PSScriptRoot 'package.json'))) {
            npm init -y *> $null
        }
        npm install --no-audit --no-fund playwright
        npx playwright install chromium
    } finally {
        Pop-Location
    }
}

Push-Location $PSScriptRoot
try {
    node capture.js
} finally {
    Pop-Location
}
